<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="<?= e(site_url('themes/newspress/assets/style.css')) ?>"></head><body><div class="top">THE DAILY EDITION</div><header class="wrap masthead"><a href="<?= e(site_url()) ?>">PAPER CAST</a></header><nav><div class="wrap"><a href="<?= e(site_url()) ?>">HOME</a><a href="<?= e(site_url('about.php')) ?>">ABOUT</a></div></nav><main class="wrap layout"><section><h2 class="section-title">SEARCH STORIES</h2><form action="<?= e(site_url('search.php')) ?>"><input name="q" value="<?= e($q) ?>" placeholder="Search stories"><button>Search</button></form><?php if($q!==''): ?><p><?= count($posts) ?> result(s) for “<?= e($q) ?>”</p><div class="stories"><?php foreach($posts as $post): ?><article><?php if($post['cover_image']): ?><img src="<?= e($post['cover_image']) ?>" alt=""><?php endif ?><small><?= e($post['category_name']??'NEWS') ?></small><h2><a href="<?= e(site_url('article.php?slug='.rawurlencode($post['slug']))) ?>"><?= e($post['title']) ?></a></h2><p><?= e($post['excerpt']?:excerpt($post['content'])) ?></p></article><?php endforeach ?><?php if(!$posts): ?><p>No matching stories.</p><?php endif ?></div><?php endif ?></section></main></body></html>